-- 判決不只「對／錯」：電路的方程組可以「欠定」，也可以「在額定內」。
-- 變數是節點電位 u1、u2 與電流 i；一條方程是 (係數, 右邊)。
import linsys

def ip (n : Nat) : Int := pos n
def im (n : Nat) : Int := neg_int (pos n)

-- ① 一個 5 V 電源、沒有接地：u1 − u2 = 5
def src5 : (List Int) × Int := (cons (ip 1) (cons (im 1) nil), ip 5)
def floating : List ((List Int) × Int) := cons src5 nil

-- 要求唯一工作點 ⟹ 欠定（不是錯）：缺一條定下 u1 或 u2 的方程（一顆地）。
-- 編輯器會在這裡標出缺什麼。
theorem opPoint : LinUnique floating := by { linsolve [u1, u2] }

-- ② 帶內阻 1 Ω 的 5 V 與 3 V 電源並聯（模型）：u1 − u2 + i = 5、u1 − u2 − i = 3、u2 = 0
def srcA : (List Int) × Int := (cons (ip 1) (cons (im 1) (cons (ip 1) nil)), ip 5)
def srcB : (List Int) × Int := (cons (ip 1) (cons (im 1) (cons (im 1) nil)), ip 3)
def gnd : (List Int) × Int := (cons (ip 0) (cons (ip 1) (cons (ip 0) nil)), ip 0)
@[model] def realSources : List ((List Int) × Int) := cons srcA (cons srcB (cons gnd nil))

-- 循環電流 |i| ≤ 2 A（第 2 個變數，界 2/1）：通過，判決帶著「在 realSources 這個模型底下」的額定假設。
-- 把界改成 (pos 1) 1（= 1/2 A）試試：超出額定，不通過。
theorem rated : LinBound realSources 2 bAbsLe (pos 2) 0 := by { linsolve [u1, u2, i] }

import meta

-- ① 巨集：把既有的 tactic 組成一個新名字
tactic close := { repeat intro; first | assumption | exact zero }

def pick : Nat -> Nat -> Nat := by { close }
def none0 : Nat := by { close }

-- ② 程式：用 Cella 寫的判定程序找證明（lib/meta.cella）
--    decideBool 把目標讀成資料（Expr），算出兩邊的值，相等就交出證明
def t1 : not (and true false) ≡ true := by { decideBool }
def t2 : or false (and true true) ≡ true := by { decideBool }

-- 交出的項一樣要通過兩個 kernel：tactic 只負責「找」，寫錯最多是證不出來
-- 試試把 t1 改成 `≡ false`：decideBool 會說它找不到
